                atualB = atualB->proximo;
            }
            else // Colunas iguais (soma)
            {
                double soma_val = atualA->valor + atualB->valor;
                resultado->inserir(i, atualA->coluna, soma_val);
                atualA = atualA->proximo;
                atualB = atualB->proximo;
            }
