            resultado->inserir(i, atualB->coluna, atualB->valor);
            atualB = atualB->proximo;
        }
    }

    return resultado;
}

// *** FUNÇÃO MULTIPLY (Implementação Otimizada) ***
SparseMatrix *multiply(SparseMatrix *A, SparseMatrix *B)
{
    if (A->getColunas() != B->getLinhas())
    {
        std::cout << "O número de colunas da matriz A deve ser igual ao número de linhas da matriz B para realizar a multiplicação." << std::endl;
        return nullptr;
    }

    int linhasA = A->getLinhas();
    int colunasB = B->getColunas();
    int colunasA = A->getColunas(); // Também igual a linhasB

    SparseMatrix *resultado = new SparseMatrix(linhasA, colunasB);

    // Estratégia: Iterar sobre as linhas de A e as colunas de B.
    // Para otimização real, B deveria ser transposta, mas vamos manter a iteração linha por linha.

    for (int i = 0; i < linhasA; i++) // Linhas de A (e do resultado)
    {
        Node* atualA = A->getLinhaStart(i);

        for (int j = 0; j < colunasB; j++) // Colunas de B (e do resultado)
        {
            double valor = 0.0;

            // A multiplicação requer somar A[i, k] * B[k, j]
            // Precisamos iterar sobre os elementos NÃO NULOS da linha i de A
            while (atualA != nullptr)
            {
                int k = atualA->coluna; // k é a coluna de A (e linha de B)

                // Verifica se B tem um elemento não nulo na linha k e coluna j
                // Nota: O get(k, j) ainda é O(N) se for implementado por busca linear, 
                // mas vamos usar o get por simplicidade, pois uma otimização completa requer
                // acesso rápido a colunas de B, o que é complexo sem uma estrutura de coluna.
                if (B->get(k, j) != 0.0)
                {
                    valor += atualA->valor * B->get(k, j);
                }

                atualA = atualA->proximo;
            }

            if (valor != 0.0) {
                resultado->inserir(i, j, valor);
            }
        }
    }

    return resultado;
